{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C16"],
      "claim": "Acalabrutinib, which shares the proline-amide–heteroaryl motif present in the query, has an absolute oral bioavailability of 25.3% in healthy subjects, directly supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Tazemetostat, measured in the fasted state with an oral tablet versus IV microdose, has a median absolute bioavailability of 31.8% (range 20.2–49.8%), supporting F ≥20% under the query's fasted condition.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Encorafenib, which contains a methyl carbamate like the query, is rapidly and nearly completely absorbed with an estimated bioavailability of at least 86% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Anagliptin, a proline-amide-containing DPP-4 inhibitor, has oral bioavailability >73% in patients, supporting high F for the query's proline-amide scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Tolvaptan has a mean absolute bioavailability of 56% in humans, providing additional evidence that amide/heteroaryl drug-like molecules in this series achieve F well above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Asciminib has an absolute bioavailability of approximately 73% in humans, supporting high F for a heteroaryl amide with moderate polarity.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All retrieved human oral bioavailability measurements for structurally related proline-amide/heteroaryl and carbamate-containing drugs are ≥25%, with most in the 50–86% range. The closest analogues, acalabrutinib and tazemetostat, are just above the 20% threshold, so the query is predicted high, though with moderate confidence because the query is a larger, more polar dimeric architecture not directly represented by the evidence.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement exists for the query molecule itself.",
    "No retrieved evidence covers a symmetric dimeric bis-proline-amide/carbamate scaffold; the closest analogues are monomeric and smaller.",
    "The potential negative impact of the query's high molecular weight and TPSA on permeability is not directly captured by the retrieved high-F analogues."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C16", "C30", "C17", "C27"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "human absolute oral bioavailability of proline-amide/heteroaryl drugs"
    }
  ],
  "revision_action": "initial"
}

